import glob,os,re,zlib,base64
for p in sorted(glob.glob('/app/documents/*.pdf')):
 print('\n### '+os.path.basename(p)+' ###')
 d=open(p,'rb').read()
 for n,m in enumerate(re.finditer(rb'stream\r?\n(.*?)\r?\nendstream',d,re.S),1):
  x=m.group(1)
  try:
   if b'/ASCII85Decode' in d[max(0,m.start()-200):m.start()]: x=base64.a85decode(x, adobe=True)
   if b'/FlateDecode' in d[max(0,m.start()-200):m.start()]: x=zlib.decompress(x)
  except Exception as e: print('stream',n,'decode error',e); continue
  print('--- stream',n,'---')
  print(x.decode('latin1','ignore'))
